CASES = [("edges", EDGES, EDGES_OUT), ("contexts", CONTEXTS, CONTEXTS_OUT),
         ("statics", STATICS, STATICS_OUT)]


@pytest.mark.parametrize("flags", [(), ("--int", "32")], ids=["int16", "int32"])
@pytest.mark.parametrize("name,source,expected", CASES,
                         ids=[c[0] for c in CASES])
def test_conversions_match_the_host(tmp_path, flags, name, source, expected):
    assert build_and_run(tmp_path, source, flags) == expected


def test_array_initializers_convert(tmp_path):
    assert build_and_run(tmp_path, ARRAYS) == ARRAYS_OUT
